import {readFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';

let frozenReference;
const reference=()=>frozenReference??=readFile(new URL('./default-padded-three-material-small-domains.json',import.meta.url),'utf8').then(JSON.parse);
const signed=r=>{if(r.length<3)return 0;const o=r[0];return r.reduce((s,a,i)=>{const b=r[(i+1)%r.length];return s+(a[0]-o[0])*(b[1]-o[1])-(b[0]-o[0])*(a[1]-o[1]);},0)/2;};
function intersection(a,b){let r=a;const sign=signed(b)<0?-1:1;for(let i=0;i<b.length;i++){const p=b[i],q=b[(i+1)%b.length],side=v=>sign*((q[0]-p[0])*(v[1]-p[1])-(q[1]-p[1])*(v[0]-p[0])),next=[];for(let j=0;j<r.length;j++){const u=r[j],v=r[(j+1)%r.length],du=side(u),dv=side(v);if(du>=0)next.push(u);if((du>=0)!==(dv>=0)){const t=du/(du-dv);next.push([u[0]+(v[0]-u[0])*t,u[1]+(v[1]-u[1])*t]);}}r=next;if(!r.length)break;}return Math.abs(signed(r));}
function faceGeometry(surface){const v=new Map(surface.vertices.map(p=>[p.id,[p.xMm,p.yMm,p.zMm]])),faces=new Map();for(const f of surface.faces){const p=f.vertices.map(id=>v.get(id));if(p.some(p=>!p))throw Error('SOURCE_VERTEX_MISSING');const order=[0,1,2].sort((a,b)=>p[a][0]-p[b][0]||p[a][1]-p[b][1]||p[a][2]-p[b][2]),q=order.map(i=>p[i]),u=q[1].map((n,i)=>n-q[0][i]),w=q[2].map((n,i)=>n-q[0][i]);faces.set(f.id,{key:JSON.stringify({region:f.region,xyz:q}),order,areaMm2:Math.hypot(u[1]*w[2]-u[2]*w[1],u[2]*w[0]-u[0]*w[2],u[0]*w[1]-u[1]*w[0])/2});}return faces;}
const group=rows=>{const m=new Map();for(const row of rows){const a=m.get(row.sourceFaceGeometryKey)??[];a.push(row);m.set(row.sourceFaceGeometryKey,a);}return m;};

/** Read-only small-panel identity audit. No worker, solver or production
 * material/palette helper is used. Physical source geometry must match exactly
 * after UUID/array-order normalization. Every candidate triangle is compared
 * bidirectionally with one whole, independently established connected domain. */
export async function auditSmallPhysicalPanels(project,{thresholdMm2=100,run}={}){
 const chosen=run??(project.bindings?.length?{pieces:project.pieces,bindings:project.bindings}:project.surfaceRun),globalIssues=[];
 let expected,source;
 try{expected=await reference();if(!Number.isFinite(thresholdMm2)||thresholdMm2<=0||thresholdMm2>expected.thresholdMm2)globalIssues.push({kind:'UNSUPPORTED_DOMAIN_SNAPSHOT_THRESHOLD',thresholdMm2});if(!project.surface||!chosen?.pieces||!chosen?.bindings)throw Error('SOURCE_OR_CANDIDATE_MISSING');source=faceGeometry(project.surface);}catch(error){return{passed:false,thresholdMm2,sourceCompatible:false,globalIssues:[...globalIssues,{kind:'DOMAIN_REFERENCE_UNAVAILABLE',message:error.message}],panels:(chosen?.pieces??project.pieces??[]).map(p=>({pieceId:p.id,name:p.name,color:p.color,allowedTrueSmallDomain:false,issues:[{kind:'DOMAIN_REFERENCE_UNAVAILABLE'}]}))};}
 const sourcePhysicalSha256=createHash('sha256').update(JSON.stringify([...source.values()].map(r=>r.key).sort())).digest('hex'),sourceCompatible=sourcePhysicalSha256===expected.sourcePhysicalSha256&&project.surface.faces.length===expected.sourceFaces;
 if(!sourceCompatible)globalIssues.push({kind:'SOURCE_GEOMETRY_DIFFERS_FROM_FROZEN_DOMAINS',expected:expected.sourcePhysicalSha256,actual:sourcePhysicalSha256});
 const domains=expected.domains.filter(d=>d.areaMm2<thresholdMm2).map(d=>({...d,groups:group(d.support)})),bindings=new Map(chosen.bindings.map(b=>[b.pieceId,b])),panels=[],physicalAreaByColor={};
 for(const p of chosen.pieces){const b=bindings.get(p.id),rows=[],issues=[];let areaMm2=0;
  if(!b?.trim?.triangles?.length)issues.push({kind:'TRIM_PROVENANCE_MISSING'});
  for(const t of b?.trim?.triangles??[]){const f=source.get(t.faceId);if(!f){issues.push({kind:'SOURCE_FACE_MISSING',faceId:t.faceId});continue;}const w=t.barycentric;if(w?.length!==3||w.some(w=>w.length!==3||w.some(n=>!Number.isFinite(n)||n < -expected.limits.barycentric||n>1+expected.limits.barycentric)||Math.abs(w.reduce((s,n)=>s+n,0)-1)>expected.limits.barycentric)){issues.push({kind:'INVALID_SOURCE_SUPPORT',faceId:t.faceId});continue;}const polygon=w.map(w=>[w[f.order[1]],w[f.order[2]]]);areaMm2+=Math.abs(signed(polygon))*2*f.areaMm2;rows.push({sourceFaceGeometryKey:f.key,sourceFaceAreaMm2:f.areaMm2,polygon});}
  physicalAreaByColor[p.color]=(physicalAreaByColor[p.color]??0)+areaMm2;
  if(!issues.length&&areaMm2>=thresholdMm2)continue;
  const groups=group(rows),matches=[];
  for(const d of domains.filter(d=>d.color===p.color)){let commonAreaMm2=0,candidateAreaMm2=0,domainAreaMm2=0,maxCandidateDifferenceRatio=0,maxDomainDifferenceRatio=0,maxCandidateOverlapRatio=0;
   for(const key of new Set([...groups.keys(),...d.groups.keys()])){const a=groups.get(key)??[],b=d.groups.get(key)??[],physical=(a[0]??b[0]).sourceFaceAreaMm2,ca=a.reduce((s,r)=>s+Math.abs(signed(r.polygon)),0),da=b.reduce((s,r)=>s+Math.abs(signed(r.polygon)),0),common=a.reduce((s,r)=>s+b.reduce((n,t)=>n+intersection(r.polygon,t.polygon),0),0);let overlap=0;for(let i=0;i<a.length;i++)for(let j=i+1;j<a.length;j++)overlap+=intersection(a[i].polygon,a[j].polygon);candidateAreaMm2+=ca*2*physical;domainAreaMm2+=da*2*physical;commonAreaMm2+=common*2*physical;maxCandidateDifferenceRatio=Math.max(maxCandidateDifferenceRatio,2*Math.abs(ca-common));maxDomainDifferenceRatio=Math.max(maxDomainDifferenceRatio,2*Math.abs(da-common));maxCandidateOverlapRatio=Math.max(maxCandidateOverlapRatio,2*overlap);}
   matches.push({domainId:d.id,color:d.color,expectedDomainAreaMm2:d.areaMm2,independentDomainAreaMm2:domainAreaMm2,candidateAreaMm2,commonAreaMm2,candidateWithinDomainRatio:candidateAreaMm2?commonAreaMm2/candidateAreaMm2:0,domainCoveredByCandidateRatio:domainAreaMm2?commonAreaMm2/domainAreaMm2:0,maxCandidateDifferenceRatio,maxDomainDifferenceRatio,maxCandidateOverlapRatio,completeBidirectionalSupport:maxCandidateDifferenceRatio<=expected.limits.coverageRatio&&maxDomainDifferenceRatio<=expected.limits.coverageRatio&&maxCandidateOverlapRatio<=expected.limits.coverageRatio});}
  const complete=matches.filter(m=>m.completeBidirectionalSupport),allowedTrueSmallDomain=sourceCompatible&&!globalIssues.length&&!issues.length&&complete.length===1;
  if(!allowedTrueSmallDomain)issues.push({kind:complete.length>1?'AMBIGUOUS_COMPLETE_DOMAIN':matches.some(m=>m.commonAreaMm2>0)?'INCOMPLETE_OR_EXTRA_DOMAIN_SUPPORT':'NOT_AN_ESTABLISHED_COMPLETE_SMALL_DOMAIN'});
  panels.push({pieceId:p.id,name:p.name,color:p.color,areaMm2,allowedTrueSmallDomain,matchedDomain:complete.length===1?complete[0]:null,candidateDomains:matches.filter(m=>m.commonAreaMm2>0||m.completeBidirectionalSupport),issues});
 }
 for(const d of domains){const represented=panels.filter(p=>p.allowedTrueSmallDomain&&p.matchedDomain?.domainId===d.id);if(represented.length!==1)globalIssues.push({kind:represented.length?'EXPECTED_SMALL_DOMAIN_DUPLICATED':'EXPECTED_SMALL_DOMAIN_MISSING_OR_FRAGMENTED',domainId:d.id,color:d.color,areaMm2:d.areaMm2,completeCandidateCount:represented.length});}
 return{passed:!globalIssues.length&&panels.every(p=>p.allowedTrueSmallDomain),thresholdMm2,sourceCompatible,sourcePhysicalSha256,expectedSourcePhysicalSha256:expected.sourcePhysicalSha256,sourceFaces:project.surface.faces.length,referenceInputSha256:expected.inputSha256,referenceRunSha256:expected.baselineRunSha256,limits:expected.limits,expectedMaterialAreasByColor:expected.expectedMaterialAreasByColor,physicalAreaByColor,globalIssues,trueSmallDomains:domains.map(({groups,support,...d})=>d),panels,scope:'Below-threshold panel identity and complete presence of each established true small domain. Reported per-colour totals are diagnostics for the caller existing coverage gate; full spatial colour coverage, locked seams, UV, manufacturing and10–50 panel-count gates remain separate. White and nonwhite whole independent domains use identical support rules. No area whitelist or missing-baseline fallback.'};
}
